import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Process lines
  const processedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    let discountPercent;
    if ('discountPercent' in line) {
      discountPercent = validateDiscountPercent(line.discountPercent);
      if (discountPercent === null) {
        return fail('DISCOUNT_INVALID');
      }
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  });
}

export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const discount = lineTotal(line) * discountPercent / 100;
  return Math.max(0, discount);
}

export function lineVat(line) {
  const amount = lineTotal(line) - lineDiscount(line);
  const vat = amount * line.vatRate / 100;
  return Math.max(0, roundCents(vat));
}

export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = subtotal - discount + vat;
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    total: Math.max(0, total),
  };
}

export function addLine(invoice, params) {
  const { sku, qty, discountPercent } = params;

  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Determine discountPercent: explicit value wins, otherwise use tier discount
  let validatedDiscount;
  if ('discountPercent' in params) {
    validatedDiscount = validateDiscountPercent(discountPercent);
    if (validatedDiscount === null) {
      return fail('DISCOUNT_INVALID');
    }
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) return customerResult;
    const customer = customerResult.value;
    validatedDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map(line => ({ ...line }));

  const existingLineIndex = newLines.findIndex(line => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
      discountPercent: 'discountPercent' in params ? validatedDiscount : newLines[existingLineIndex].discountPercent,
    };
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: validatedDiscount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex(line => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

